-- Delete rows that carry values the narrowed CHECK constraints no longer allow (system never went live; Stripe plan D11, D38)
DELETE FROM "seller"."kyc_review_issues" WHERE field NOT IN ('product_type', 'website_url', 'business.company_name', 'business.tax_id', 'business.company_register_date', 'business.company_address', 'business.company_phone', 'business.company_documents');
DELETE FROM "seller"."account_identity_hashes" WHERE field NOT IN ('TAX_ID', 'BANK_FINGERPRINT');
DELETE FROM "seller"."measure_identities" WHERE kind NOT IN ('TAX_ID', 'BANK_ACCOUNT');
DELETE FROM "seller"."kyc_documents" WHERE slot <> 'COMPANY_DOCUMENT';
-- The read log changes shape (who, which, when; no grant, D36): old rows hang on grants that are dropped
DELETE FROM "seller"."kyc_document_accesses";
-- Modify "account_identity_hashes" table
ALTER TABLE "seller"."account_identity_hashes" DROP CONSTRAINT "account_identity_hashes_field_check", ADD CONSTRAINT "account_identity_hashes_field_check" CHECK (field = ANY (ARRAY['TAX_ID'::text, 'BANK_FINGERPRINT'::text]));
-- Modify "kyc_applications" table
ALTER TABLE "seller"."kyc_applications" DROP CONSTRAINT "kyc_applications_bank_account_check", DROP CONSTRAINT "kyc_applications_bank_code_check", DROP CONSTRAINT "kyc_applications_bank_name_check", DROP CONSTRAINT "kyc_applications_birth_date_check", DROP CONSTRAINT "kyc_applications_english_name_check", DROP CONSTRAINT "kyc_applications_hash_length_check", DROP CONSTRAINT "kyc_applications_id_card_check", DROP CONSTRAINT "kyc_applications_issue_date_check", DROP CONSTRAINT "kyc_applications_issue_location_check", DROP CONSTRAINT "kyc_applications_issue_type_check", DROP CONSTRAINT "kyc_applications_real_name_check", DROP CONSTRAINT "kyc_applications_rep_id_card_check", DROP CONSTRAINT "kyc_applications_tax_id_hash_check", DROP CONSTRAINT "kyc_applications_purged_check", ADD CONSTRAINT "kyc_applications_purged_check" CHECK ((pii_purged_at IS NULL) OR ((website_url IS NULL) AND (company_name IS NULL) AND (tax_id IS NULL) AND (company_register_date IS NULL) AND (company_town_code IS NULL) AND (company_address_detail IS NULL) AND (company_phone IS NULL))), DROP CONSTRAINT "kyc_applications_type_fields_check", ADD CONSTRAINT "kyc_applications_type_fields_check" CHECK ((seller_type = 'COMPANY'::text) OR ((company_name IS NULL) AND (tax_id IS NULL) AND (company_register_date IS NULL) AND (company_town_code IS NULL) AND (company_address_detail IS NULL) AND (company_phone IS NULL))), DROP COLUMN "real_name", DROP COLUMN "birth_date", DROP COLUMN "id_card_no_enc", DROP COLUMN "id_card_hash", DROP COLUMN "id_card_hash_key", DROP COLUMN "id_card_issue_date", DROP COLUMN "id_card_issue_type", DROP COLUMN "id_card_issue_location", DROP COLUMN "english_name", DROP COLUMN "bank_name", DROP COLUMN "bank_code", DROP COLUMN "bank_account_enc", DROP COLUMN "bank_account_hash", DROP COLUMN "bank_account_hash_key", DROP COLUMN "tax_id_hash", DROP COLUMN "tax_id_hash_key", DROP COLUMN "rep_id_card_no_enc", DROP COLUMN "rep_id_card_hash", DROP COLUMN "rep_id_card_hash_key";
-- Modify "kyc_documents" table
ALTER TABLE "seller"."kyc_documents" DROP CONSTRAINT "kyc_documents_slot_check", DROP CONSTRAINT "kyc_documents_pkey", DROP CONSTRAINT "kyc_documents_position_check", ADD CONSTRAINT "kyc_documents_position_check" CHECK (("position" >= 0) AND ("position" < 10)), DROP COLUMN "slot", ADD PRIMARY KEY ("application_id", "position");
-- Modify "kyc_review_issues" table
ALTER TABLE "seller"."kyc_review_issues" DROP CONSTRAINT "kyc_review_issues_asset_check", ADD CONSTRAINT "kyc_review_issues_asset_check" CHECK ((document_asset_id IS NULL) OR ((document_asset_id <> ''::text) AND (field = 'business.company_documents'::text))), DROP CONSTRAINT "kyc_review_issues_field_check", ADD CONSTRAINT "kyc_review_issues_field_check" CHECK (field = ANY (ARRAY['product_type'::text, 'website_url'::text, 'business.company_name'::text, 'business.tax_id'::text, 'business.company_register_date'::text, 'business.company_address'::text, 'business.company_phone'::text, 'business.company_documents'::text]));
-- Modify "measure_identities" table
ALTER TABLE "seller"."measure_identities" DROP CONSTRAINT "measure_identities_kind_check", ADD CONSTRAINT "measure_identities_kind_check" CHECK (kind = ANY (ARRAY['TAX_ID'::text, 'BANK_ACCOUNT'::text]));
-- Modify "kyc_document_accesses" table
ALTER TABLE "seller"."kyc_document_accesses" DROP CONSTRAINT "kyc_document_accesses_slot_check", DROP CONSTRAINT "kyc_document_accesses_position_check", ADD CONSTRAINT "kyc_document_accesses_position_check" CHECK (("position" >= 0) AND ("position" < 10)), ADD CONSTRAINT "kyc_document_accesses_admin_check" CHECK (admin_id > 0), DROP COLUMN "reveal_id", DROP COLUMN "slot", ADD COLUMN "admin_id" bigint NOT NULL, ADD CONSTRAINT "kyc_document_accesses_application_id_fkey" FOREIGN KEY ("application_id") REFERENCES "seller"."kyc_applications" ("application_id") ON UPDATE NO ACTION ON DELETE NO ACTION;
-- Drop "kyc_identity_hashes" table
DROP TABLE "seller"."kyc_identity_hashes";
-- Drop "kyc_reveals" table
DROP TABLE "seller"."kyc_reveals";
